import { test, expect } from '@playwright/test';

test.describe('File Upload Button Disabled During Upload', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should disable upload button while file is uploading', async ({ page }) => {
    // Verify upload button is visible and enabled initially
    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await expect(uploadButton).toBeVisible();
    await expect(uploadButton).toBeEnabled();

    // Intercept the file upload API call
    await page.route('**/api/upload', (route) => {
      route.abort('Upload in progress');
    });

    // Attempt to upload a file
    const fileInput = page.getByLabel(/choose file/i);
    await fileInput.setInputFiles('tests/fixtures/sample.pdf');

    // Verify upload button is disabled after file selection
    await expect(uploadButton).toBeDisabled();

    // Verify upload progress indicator is visible
    const progressIndicator = page.getByRole('progressbar');
    await expect(progressIndicator).toBeVisible();

    // Verify upload button is still disabled
    await expect(uploadButton).toBeDisabled();

    // Verify error message is displayed
    const errorMessage = page.getByText(/upload in progress/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should re-enable upload button after upload completes', async ({ page }) => {
    // Verify upload button is visible and enabled initially
    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await expect(uploadButton).toBeVisible();
    await expect(uploadButton).toBeEnabled();

    // Intercept the file upload API call
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Attempt to upload a file
    const fileInput = page.getByLabel(/choose file/i);
    await fileInput.setInputFiles('tests/fixtures/sample.pdf');

    // Verify upload button is disabled while uploading
    await expect(uploadButton).toBeDisabled();

    // Verify upload progress indicator is visible
    const progressIndicator = page.getByRole('progressbar');
    await expect(progressIndicator).toBeVisible();

    // Verify upload button is still disabled
    await expect(uploadButton).toBeDisabled();

    // Verify upload completes successfully
    await page.waitForResponse(response => response.url().includes('/api/upload') && response.status() === 200);

    // Verify upload button is re-enabled after upload completes
    await expect(uploadButton).toBeEnabled();

    // Verify success message is displayed
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).toBeVisible();
  });
});
